//! Run-time binding to the MuJoCo C library.
//!
//! Functions are resolved with `libloading`; struct fields are read through a
//! per-version layout table (MuJoCo has no stable ABI for `mjModel`/`mjData`
//! fields). Versions without a table entry are refused. The table is
//! generated by `tools/mujoco_layout.c`, and every load cross-checks the sizes
//! read through it against `mj_stateSize`.

use std::ffi::{CStr, CString, c_char, c_int, c_void};
use std::path::Path;

use libloading::Library;

/// Field offsets and enum values for one MuJoCo release.
#[derive(Debug, Clone, Copy)]
pub struct Layout {
    pub version: i32,
    /// Width of `mjtSize` size fields.
    pub size_bytes: usize,
    /// Width of the integer arrays (`jnt_type`, `sensor_adr`, ...).
    pub index_bytes: usize,
    pub model_nq: usize,
    pub model_nv: usize,
    pub model_nu: usize,
    pub model_nbody: usize,
    pub model_njnt: usize,
    pub model_nsensor: usize,
    pub model_nsensordata: usize,
    pub model_timestep: usize,
    pub model_jnt_type: usize,
    pub model_jnt_qposadr: usize,
    pub model_jnt_dofadr: usize,
    pub model_sensor_dim: usize,
    pub model_sensor_adr: usize,
    pub data_time: usize,
    pub data_qpos: usize,
    pub data_qvel: usize,
    pub data_ctrl: usize,
    pub data_sensordata: usize,
    pub data_xpos: usize,
    pub data_xquat: usize,
    pub obj_body: i32,
    pub obj_joint: i32,
    pub obj_actuator: i32,
    pub obj_sensor: i32,
    pub state_qpos: i32,
    pub state_qvel: i32,
}

/// Known releases. Generated with `tools/mujoco_layout.c`.
pub const LAYOUTS: &[Layout] = &[
    // MuJoCo 3.15.0 (x86_64 Linux, from the `mujoco` Python wheel).
    Layout {
        version: 3015000,
        size_bytes: 8,
        index_bytes: 4,
        model_nq: 0,
        model_nv: 8,
        model_nu: 16,
        model_nbody: 48,
        model_njnt: 88,
        model_nsensor: 496,
        model_nsensordata: 736,
        model_timestep: 784,
        model_jnt_type: 2096,
        model_jnt_qposadr: 2104,
        model_jnt_dofadr: 2112,
        model_sensor_dim: 5072,
        model_sensor_adr: 5080,
        data_time: 160648,
        data_qpos: 160688,
        data_qvel: 160696,
        data_ctrl: 160736,
        data_sensordata: 160808,
        data_xpos: 160840,
        data_xquat: 160848,
        obj_body: 1,
        obj_joint: 3,
        obj_actuator: 19,
        obj_sensor: 20,
        state_qpos: 2,
        state_qvel: 4,
    },
];

/// `mjtJoint`.
pub mod joint_type {
    pub const FREE: i32 = 0;
    pub const BALL: i32 = 1;
    pub const SLIDE: i32 = 2;
    pub const HINGE: i32 = 3;
}

type LoadXml =
    unsafe extern "C" fn(*const c_char, *const c_void, *mut c_char, c_int) -> *mut c_void;
type MakeData = unsafe extern "C" fn(*const c_void) -> *mut c_void;
type Step = unsafe extern "C" fn(*const c_void, *mut c_void);
type Delete = unsafe extern "C" fn(*mut c_void);
type Version = unsafe extern "C" fn() -> c_int;
type StateSize = unsafe extern "C" fn(*const c_void, c_int) -> c_int;
type Id2Name = unsafe extern "C" fn(*const c_void, c_int, c_int) -> *const c_char;
type Name2Id = unsafe extern "C" fn(*const c_void, c_int, *const c_char) -> c_int;

/// The resolved MuJoCo functions.
pub struct Api {
    pub layout: Layout,
    pub version_string: String,
    load_xml: LoadXml,
    make_data: MakeData,
    step: Step,
    forward: Step,
    reset_data: Step,
    delete_data: Delete,
    delete_model: Delete,
    state_size: StateSize,
    id2name: Id2Name,
    name2id: Name2Id,
    _lib: Library,
}

/// Environment variable naming the MuJoCo shared library to load.
pub const LIB_ENV: &str = "RURO_MUJOCO_LIB";

impl Api {
    /// Loads the library at `path`, or from `RURO_MUJOCO_LIB`, or `libmujoco.so`.
    pub fn load(path: Option<&str>) -> Result<Api, String> {
        let path = path
            .filter(|p| !p.is_empty())
            .map(str::to_owned)
            .or_else(|| std::env::var(LIB_ENV).ok())
            .unwrap_or_else(|| "libmujoco.so".into());
        // SAFETY: loading MuJoCo runs its (side-effect free) initialisers.
        let lib = unsafe { Library::new(&path) }.map_err(|e| {
            format!("cannot load MuJoCo from `{path}` ({e}); set {LIB_ENV} to libmujoco.so's path")
        })?;
        // SAFETY: symbol types match the C declarations in mujoco.h.
        unsafe {
            macro_rules! sym {
                ($name:literal) => {
                    *lib.get(concat!($name, "\0").as_bytes())
                        .map_err(|e| format!("{}: {e}", $name))?
                };
            }
            let version: Version = sym!("mj_version");
            let v = version();
            let layout = LAYOUTS.iter().find(|l| l.version == v).copied().ok_or_else(|| {
                let known: Vec<String> = LAYOUTS.iter().map(|l| version_name(l.version)).collect();
                format!(
                    "MuJoCo {} is not supported (known: {}); generate its layout with tools/mujoco_layout.c",
                    version_name(v),
                    known.join(", ")
                )
            })?;
            let vs: unsafe extern "C" fn() -> *const c_char = sym!("mj_versionString");
            let version_string = CStr::from_ptr(vs()).to_string_lossy().into_owned();
            Ok(Api {
                layout,
                version_string,
                load_xml: sym!("mj_loadXML"),
                make_data: sym!("mj_makeData"),
                step: sym!("mj_step"),
                forward: sym!("mj_forward"),
                reset_data: sym!("mj_resetData"),
                delete_data: sym!("mj_deleteData"),
                delete_model: sym!("mj_deleteModel"),
                state_size: sym!("mj_stateSize"),
                id2name: sym!("mj_id2name"),
                name2id: sym!("mj_name2id"),
                _lib: lib,
            })
        }
    }
}

fn version_name(v: i32) -> String {
    format!("{}.{}.{}", v / 1_000_000, v / 1000 % 1000, v % 1000)
}

/// A loaded model and its simulation state.
pub struct Sim {
    api: Api,
    model: *mut c_void,
    data: *mut c_void,
    pub nq: usize,
    pub nv: usize,
    pub nu: usize,
    pub nbody: usize,
    pub njnt: usize,
    pub nsensor: usize,
    pub nsensordata: usize,
}

// SAFETY: model and data are owned exclusively by this struct; MuJoCo has no
// thread affinity for them.
unsafe impl Send for Sim {}

impl Sim {
    pub fn load(api: Api, model_path: &Path) -> Result<Sim, String> {
        let cpath =
            CString::new(model_path.to_string_lossy().as_bytes()).map_err(|e| e.to_string())?;
        let mut err = vec![0 as c_char; 1024];
        // SAFETY: valid C string and error buffer of the stated size.
        let model = unsafe {
            (api.load_xml)(
                cpath.as_ptr(),
                std::ptr::null(),
                err.as_mut_ptr(),
                err.len() as c_int,
            )
        };
        if model.is_null() {
            // SAFETY: MuJoCo NUL-terminates the error message.
            let msg = unsafe { CStr::from_ptr(err.as_ptr()) }
                .to_string_lossy()
                .into_owned();
            return Err(format!("loading {}: {msg}", model_path.display()));
        }
        // SAFETY: `model` is a valid mjModel.
        let data = unsafe { (api.make_data)(model) };
        if data.is_null() {
            // SAFETY: model was allocated by mj_loadXML.
            unsafe { (api.delete_model)(model) };
            return Err("mj_makeData failed".into());
        }
        let mut sim = Sim {
            api,
            model,
            data,
            nq: 0,
            nv: 0,
            nu: 0,
            nbody: 0,
            njnt: 0,
            nsensor: 0,
            nsensordata: 0,
        };
        let l = sim.api.layout;
        sim.nq = sim.model_size(l.model_nq);
        sim.nv = sim.model_size(l.model_nv);
        sim.nu = sim.model_size(l.model_nu);
        sim.nbody = sim.model_size(l.model_nbody);
        sim.njnt = sim.model_size(l.model_njnt);
        sim.nsensor = sim.model_size(l.model_nsensor);
        sim.nsensordata = sim.model_size(l.model_nsensordata);
        // Cross-check the layout table against the layout-free API.
        // SAFETY: valid model.
        let (nq, nv) = unsafe {
            (
                (sim.api.state_size)(model, l.state_qpos) as usize,
                (sim.api.state_size)(model, l.state_qvel) as usize,
            )
        };
        if (nq, nv) != (sim.nq, sim.nv) || sim.nbody == 0 || sim.nbody > 1 << 24 {
            return Err(format!(
                "MuJoCo layout mismatch (nq {} vs {nq}, nv {} vs {nv}, nbody {}); refusing to run",
                sim.nq, sim.nv, sim.nbody
            ));
        }
        sim.forward();
        Ok(sim)
    }

    pub fn version(&self) -> &str {
        &self.api.version_string
    }

    fn model_size(&self, off: usize) -> usize {
        // SAFETY: `off` comes from the layout table for this exact version.
        unsafe {
            let p = (self.model as *const u8).add(off);
            match self.api.layout.size_bytes {
                8 => (p as *const i64).read_unaligned() as usize,
                _ => (p as *const i32).read_unaligned() as usize,
            }
        }
    }

    fn model_ints(&self, off: usize, len: usize) -> Vec<i64> {
        // SAFETY: the field at `off` is a pointer to `len` integers of `index_bytes` width.
        unsafe {
            let base = ((self.model as *const u8).add(off) as *const *const u8).read_unaligned();
            (0..len)
                .map(|i| match self.api.layout.index_bytes {
                    8 => (base as *const i64).add(i).read_unaligned(),
                    _ => (base as *const i32).add(i).read_unaligned() as i64,
                })
                .collect()
        }
    }

    fn data_array(&self, off: usize) -> *mut f64 {
        // SAFETY: the field at `off` is an `mjtNum*` owned by mjData.
        unsafe { ((self.data as *const u8).add(off) as *const *mut f64).read_unaligned() }
    }

    fn slice(&self, off: usize, len: usize) -> &[f64] {
        // SAFETY: array of `len` doubles inside mjData, valid for the life of `self`.
        unsafe { std::slice::from_raw_parts(self.data_array(off), len) }
    }

    fn slice_mut(&mut self, off: usize, len: usize) -> &mut [f64] {
        // SAFETY: as above, with exclusive access through &mut self.
        unsafe { std::slice::from_raw_parts_mut(self.data_array(off), len) }
    }

    pub fn timestep(&self) -> f64 {
        // SAFETY: `opt.timestep` offset from the layout table.
        unsafe {
            ((self.model as *const u8).add(self.api.layout.model_timestep) as *const f64)
                .read_unaligned()
        }
    }

    pub fn time(&self) -> f64 {
        // SAFETY: `time` offset from the layout table.
        unsafe {
            ((self.data as *const u8).add(self.api.layout.data_time) as *const f64).read_unaligned()
        }
    }

    pub fn qpos(&self) -> &[f64] {
        self.slice(self.api.layout.data_qpos, self.nq)
    }

    pub fn qpos_mut(&mut self) -> &mut [f64] {
        self.slice_mut(self.api.layout.data_qpos, self.nq)
    }

    pub fn qvel(&self) -> &[f64] {
        self.slice(self.api.layout.data_qvel, self.nv)
    }

    pub fn qvel_mut(&mut self) -> &mut [f64] {
        self.slice_mut(self.api.layout.data_qvel, self.nv)
    }

    pub fn ctrl_mut(&mut self) -> &mut [f64] {
        self.slice_mut(self.api.layout.data_ctrl, self.nu)
    }

    pub fn ctrl(&self) -> &[f64] {
        self.slice(self.api.layout.data_ctrl, self.nu)
    }

    pub fn sensordata(&self) -> &[f64] {
        self.slice(self.api.layout.data_sensordata, self.nsensordata)
    }

    /// World position of each body.
    pub fn xpos(&self) -> &[f64] {
        self.slice(self.api.layout.data_xpos, 3 * self.nbody)
    }

    /// World orientation of each body as `w, x, y, z`.
    pub fn xquat(&self) -> &[f64] {
        self.slice(self.api.layout.data_xquat, 4 * self.nbody)
    }

    /// `(type, qpos address, dof address)` of each joint.
    pub fn joints(&self) -> Vec<(i32, usize, usize)> {
        let l = self.api.layout;
        let t = self.model_ints(l.model_jnt_type, self.njnt);
        let q = self.model_ints(l.model_jnt_qposadr, self.njnt);
        let d = self.model_ints(l.model_jnt_dofadr, self.njnt);
        (0..self.njnt)
            .map(|i| (t[i] as i32, q[i] as usize, d[i] as usize))
            .collect()
    }

    /// `(name, address, dimension)` of each sensor.
    pub fn sensors(&self) -> Vec<(String, usize, usize)> {
        let l = self.api.layout;
        let adr = self.model_ints(l.model_sensor_adr, self.nsensor);
        let dim = self.model_ints(l.model_sensor_dim, self.nsensor);
        (0..self.nsensor)
            .map(|i| {
                let name = self
                    .name(l.obj_sensor, i)
                    .unwrap_or_else(|| format!("sensor{i}"));
                (name, adr[i] as usize, dim[i] as usize)
            })
            .collect()
    }

    pub fn name(&self, obj: i32, id: usize) -> Option<String> {
        // SAFETY: valid model; MuJoCo returns NULL for unnamed objects.
        let p = unsafe { (self.api.id2name)(self.model, obj, id as c_int) };
        if p.is_null() {
            return None;
        }
        // SAFETY: NUL-terminated string owned by the model.
        let s = unsafe { CStr::from_ptr(p) }.to_string_lossy().into_owned();
        (!s.is_empty()).then_some(s)
    }

    pub fn id(&self, obj: i32, name: &str) -> Option<usize> {
        let c = CString::new(name).ok()?;
        // SAFETY: valid model and C string.
        let id = unsafe { (self.api.name2id)(self.model, obj, c.as_ptr()) };
        (id >= 0).then_some(id as usize)
    }

    pub fn body_name(&self, id: usize) -> String {
        self.name(self.api.layout.obj_body, id)
            .unwrap_or_else(|| format!("body{id}"))
    }

    pub fn joint_name(&self, id: usize) -> String {
        self.name(self.api.layout.obj_joint, id)
            .unwrap_or_else(|| format!("joint{id}"))
    }

    pub fn step(&mut self) {
        // SAFETY: valid model and data.
        unsafe { (self.api.step)(self.model, self.data) }
    }

    /// Recomputes derived quantities (body poses, sensors) without advancing time.
    pub fn forward(&mut self) {
        // SAFETY: valid model and data.
        unsafe { (self.api.forward)(self.model, self.data) }
    }

    pub fn reset(&mut self) {
        // SAFETY: valid model and data.
        unsafe { (self.api.reset_data)(self.model, self.data) };
        self.forward();
    }
}

impl Drop for Sim {
    fn drop(&mut self) {
        // SAFETY: both were allocated by MuJoCo and are freed exactly once.
        unsafe {
            (self.api.delete_data)(self.data);
            (self.api.delete_model)(self.model);
        }
    }
}
